    public static string Validator(CrudNames n, string operation, IReadOnlyList<MethodParameter> fields)
    {
        var rules = new List<string>();
        if (operation == "Update" && n.IdType == "Guid")
            rules.Add("RuleFor(x => x.Id).NotEmpty();");

        foreach (MethodParameter field in fields)
        {
            string? max = n.Model.MaxLengthConstant(field.Name);
            var chain = new List<string>();

            if (field.IsString && !field.IsNullable)
                chain.Add("NotEmpty()");
            if (field.IsString && max is not null)
                chain.Add($"MaximumLength({n.Entity}.{max})");
            if (field.BareType == "Guid" && !field.IsNullable)
                chain.Add("NotEmpty()");
            if (n.Model.Properties.FirstOrDefault(p => p.Name == field.Name) is { Kind: PropertyKind.Enum })
                chain.Add("IsInEnum()");

            if (chain.Count > 0)
                rules.Add($"RuleFor(x => x.{field.Name}).{string.Join('.', chain)};");
            else if (field.IsString)
                rules.Add($"// TODO(can-gen): {field.Name} için uzunluk sınırı yok; entity'ye {field.Name}MaxLength sabiti ekle ya da: RuleFor(x => x.{field.Name}).MaximumLength(...);");
        }

        rules.Add("// TODO(can-gen): Diğer doğrulama kurallarını ekle (aralık, biçim ...). Veritabanı gerektiren kurallar BusinessRules'ta.");
        string body = string.Join("\n", rules.Select(r => "        " + r));

        return $$"""
            {{Header}}
            using FluentValidation;
            using {{n.Model.Namespace}};

            namespace {{n.FeatureNamespace}}.Commands.{{operation}};

            public sealed class {{operation}}{{n.Entity}}CommandValidator : AbstractValidator<{{operation}}{{n.Entity}}Command>
            {
                public {{operation}}{{n.Entity}}CommandValidator()
                {
            {{body}}
                }
            }

            """;
    }

