    public static string Configuration(CrudNames n)
    {
        var lines = new List<string> { $"builder.ToTable(\"{n.Plural}\", Schemas.App).HasKey(x => x.Id);", $"builder.Property(x => x.Id).HasColumnName(\"Id\");" };
        foreach (EntityProperty property in n.Model.Properties.Where(p => p.Name != "Id"))
        {
            string? max = n.Model.MaxLengthConstant(property.Name);
            string column = $".HasColumnName(\"{property.Name}\")";
            switch (property.Kind)
            {
                case PropertyKind.Scalar when property.IsString:
                    string required = property.IsNullable ? string.Empty : ".IsRequired()";
                    lines.Add(max is not null
                        ? $"builder.Property(x => x.{property.Name}){column}.HasMaxLength({n.Entity}.{max}){required};"
                        : $"builder.Property(x => x.{property.Name}){column}{required}; // TODO(can-gen): Uzunluk sınırı ver: .HasMaxLength(...)");
                    break;
                case PropertyKind.Scalar when property.BareType is "decimal" or "Decimal":
                    lines.Add($"builder.Property(x => x.{property.Name}){column}.HasPrecision(18, 2); // TODO(can-gen): Hassasiyeti kontrol et.");
                    break;
                case PropertyKind.Scalar:
                    lines.Add($"builder.Property(x => x.{property.Name}){column};");
                    break;
                case PropertyKind.Enum:
                    lines.Add($"builder.Property(x => x.{property.Name}){column}.HasConversion<string>().HasMaxLength(32);");
                    break;
                case PropertyKind.Collection:
                    lines.Add($"// TODO(can-gen): {property.Name} koleksiyonunu eşle: builder.HasMany(x => x.{property.Name}).WithOne().HasForeignKey(\"{n.Entity}Id\");");
                    break;
                case PropertyKind.Complex:
                    lines.Add($"// TODO(can-gen): {property.Name} ({property.BareType}) için eşleme yaz: value object ise builder.OwnsOne(x => x.{property.Name}), entity ise ilişki (HasOne).");
                    break;
            }
        }

        lines.Add("// TODO(can-gen): Index ve ilişkileri ekle, ör. builder.HasIndex(x => x.Name, \"UK_" + n.Plural + "_Name\").IsUnique();");
        string body = string.Join("\n", lines.Select(l => "        " + l));

        return $$"""
            {{Header}}
            using Microsoft.EntityFrameworkCore;
            using Microsoft.EntityFrameworkCore.Metadata.Builders;
            using {{n.Root}}.Persistence.Contexts;
            using {{n.Model.Namespace}};

            namespace {{n.Root}}.Persistence.EntityConfigurations;

            public sealed class {{n.Entity}}Configuration : IEntityTypeConfiguration<{{n.Entity}}>
            {
                public void Configure(EntityTypeBuilder<{{n.Entity}}> builder)
                {
            {{body}}
                }
            }

            """;
    }

