        n.Options.Secured
            ? $"\n\n    [JsonIgnore]\n    public IReadOnlyCollection<string> Permissions => [{string.Join(", ", claims.Select(c => $"{n.Plural}OperationClaims.{c}"))}];"
            : string.Empty;

